function App() {
  const [open, setOpen] = useState(false);
  return <div style={{fontFamily:"system-ui",padding:16}}><button aria-expanded={open} onClick={() => setOpen(v => !v)}>{open ? "Hide details" : "Show details"}</button><div style={{overflow:"hidden",maxHeight:open?120:0,transition:"max-height 240ms ease"}}><p>Motion helps show that this content belongs to the button.</p></div></div>;
}
